-- Expand the canonical zero-balance catalogue from the approved day-to-day
-- ledger structure. Transactions and opening balances are intentionally absent.
insert into master_inventory_items
  (id, ledger_id, sku, name, category, unit, minimum_stock_level, planned_monthly_use, active, created_by, updated_by)
select 'cat-' || lower(replace(sku, '_', '-')), ledger, sku, name, category, unit, 0, 0, true, 'catalogue-reconciliation', 'catalogue-reconciliation'
from (values
  ('components','COMP-FRAME','Frames','Finished components','ea'),('components','COMP-FORK','Forks','Finished components','ea'),('components','COMP-HEADSET','Headsets','Steering','ea'),('components','COMP-SEATPOST','Seat posts','Cockpit','ea'),('components','COMP-HANDLEBAR','Handlebars','Cockpit','ea'),('components','COMP-STEM','Stems','Cockpit','ea'),('components','COMP-SADDLE','Saddles','Cockpit','ea'),('components','COMP-CRANKSET','Cranksets','Drivetrain','ea'),('components','COMP-CHAIN','Chains','Drivetrain','ea'),('components','COMP-CASSETTE','Cassettes','Drivetrain','ea'),('components','COMP-DERAILLEUR','Derailleurs','Drivetrain','ea'),('components','COMP-SHIFTER','Shifters','Drivetrain','ea'),('components','COMP-BRAKE-CALIPER','Brake calipers','Braking','ea'),('components','COMP-BRAKE-ROTOR','Brake rotors','Braking','ea'),('components','COMP-BRAKE-PAD','Brake pads','Braking','set'),('components','COMP-WHEELSET','Wheelsets','Wheels','set'),('components','COMP-RIM','Rims','Wheels','ea'),('components','COMP-HUB','Hubs','Wheels','ea'),('components','COMP-SPOKE','Spokes and nipples','Wheels','set'),('components','COMP-TYRE','Tyres','Wheels','ea'),('components','COMP-TUBE','Tubes / tubeless valves','Wheels','set'),('components','COMP-PEDAL','Pedals','Contact points','set'),('components','COMP-CABLE','Cables and hydraulic hoses','Controls','set'),('components','COMP-BARTAPE','Bar tape / grips','Cockpit','set'),('components','COMP-BOTTLE-CAGE','Bottle cages','Accessories','ea'),('components','COMP-BEARING','Bearings and seals','Hardware','set'),('components','COMP-FASTENER','Fasteners, washers and spacers','Hardware','set'),('components','COMP-LABEL','Labels, serial plates and manuals','Packaging','set'),
  ('raw-materials','RAW-CARBON-TOW','Carbon fibre tow','Carbon','kg'),('raw-materials','RAW-CARBON-FABRIC','Carbon fabric','Carbon','m2'),('raw-materials','RAW-UNIDIRECTIONAL','Unidirectional carbon','Carbon','m2'),('raw-materials','RAW-PREPREG','Prepreg carbon','Carbon','kg'),('raw-materials','RAW-EPOXY','Epoxy resin and hardener','Resin','kg'),('raw-materials','RAW-PEEL-PLY','Peel ply','Composite process','m2'),('raw-materials','RAW-BREATHER','Breather fabric','Composite process','m2'),('raw-materials','RAW-RELEASE-FILM','Release film','Composite process','m2'),('raw-materials','RAW-VACUUM-FILM','Vacuum bag film and sealant tape','Composite process','set'),('raw-materials','RAW-FLOW-MEDIA','Flow media and vacuum hose','Composite process','set'),('raw-materials','RAW-CORE-FOAM','Core foam / honeycomb core','Core materials','m2'),('raw-materials','RAW-ALUMINIUM','Aluminium sheets and tubes','Metal','kg'),('raw-materials','RAW-INSERTS','Steel / brass / threaded inserts','Hardware','set'),('raw-materials','RAW-ADHESIVE','Structural and bonding adhesive','Adhesives','kg'),('raw-materials','RAW-PRIMER','Primer and surfacer','Finishing','litre'),('raw-materials','RAW-PAINT','Paint and clear coat','Finishing','litre'),('raw-materials','RAW-SOLVENT','Solvents, thinners and alcohol','Finishing','litre'),('raw-materials','RAW-ABRASIVE','Sandpaper, abrasive discs and blades','Finishing','set'),('raw-materials','RAW-MASKING','Masking tape and protective film','Finishing','roll'),('raw-materials','RAW-LUBRICANT','Lubricants and grease','Workshop','litre'),('raw-materials','RAW-PPE','PPE consumables','Safety','set'),('raw-materials','RAW-CLEANING','Cleaning materials','Operations','set'),
