  ('quality','QUALITY-CALIPER','Vernier calipers and micrometers','Dimensional inspection','set'),('quality','QUALITY-HEIGHT-GAUGE','Height gauges and digital scales','Dimensional inspection','set'),('quality','QUALITY-TORQUE','Torque testers','Testing','ea'),('quality','QUALITY-TEMP','Temperature and humidity meters','Calibration','set'),('quality','QUALITY-COATING','Surface and coating gauges','Inspection','set'),('quality','QUALITY-HARDNESS','Hardness testers','Testing','ea'),('quality','QUALITY-ALIGNMENT','Frame and fork alignment gauges','Inspection','set'),('quality','QUALITY-WHEEL','Wheel truing stands','Inspection','ea'),('quality','QUALITY-LOAD','Load, fatigue and impact test equipment','Testing','set'),('quality','QUALITY-DYE','Dye penetrant inspection materials','NDT','set'),('quality','QUALITY-CAL-STANDARD','Calibration standards and reference gauges','Calibration','set'),('quality','QUALITY-QUARANTINE','Quarantine racks and sample bins','Stores','set'),('quality','QUALITY-TAGS','Inspection tags and test labels','Documentation','set'),
  ('stores-tools','STORE-SHELVING','Shelving and storage cabinets','Storage','ea'),('stores-tools','STORE-DRAWERS','Drawer cabinets and parts trays','Storage','set'),('stores-tools','STORE-PALLET','Pallets and hand trucks','Material handling','set'),('stores-tools','STORE-WORKBENCH','Workbenches and vises','Workshop','set'),('stores-tools','STORE-HAND-TOOLS','Hand tools and socket sets','Workshop','set'),('stores-tools','STORE-LADDERS','Ladders and safety barriers','Safety','set'),('stores-tools','STORE-FIRE','Fire extinguishers and first-aid equipment','Safety','set'),('stores-tools','STORE-WASTE','Waste and scrap bins','Stores','set'),('stores-tools','STORE-PACKING','Finished-goods and dispatch packing equipment','Dispatch','set'),
