  ('raw-materials','CONS-STATIONERY','Stationery, paper, files and folders','Office consumables','set'),('raw-materials','CONS-TONER','Printer toner and cartridges','Office consumables','set'),('raw-materials','CONS-PANTRY','Pantry supplies and drinking water','Office consumables','set'),('raw-materials','CONS-BATTERY','Batteries and small electrical accessories','Office consumables','set'),('raw-materials','CONS-FIRST-AID','First-aid consumables','Safety consumables','set'),('raw-materials','CONS-WASTE','Packaging tape, labels and waste bags','Operations','set')
